import{_ as t,o as s,c as n,a0 as a}from"./chunks/framework.B7o6dWmz.js";const p=JSON.parse('{"title":"System Panel (Feluqa Core)","description":"The built-in control plane: first-run setup, users, privileges, roles, permissions, modules, features, configuration, audit and licensing.","frontmatter":{"icon":"layout-dashboard","title":"System Panel (Feluqa Core)","description":"The built-in control plane: first-run setup, users, privileges, roles, permissions, modules, features, configuration, audit and licensing.","summary":"Describes the planned System Control Panel as the Platform\'s `/system` administration surface, separate from business application panels. It outlines its sections and the rules governing access and administrative responsibilities.","date":"2026-10-29T00:00:00.000Z","lastmod":"2026-10-29T00:00:00.000Z","weight":4,"status":"Target","tags":["feluqa","system-panel","core","administration"],"draft":true,"author":{"name":"El Moumen Yassine","url":"https://numerimondes.com","linkedin":"https://www.linkedin.com/in/elmoumenyassine","email":"yassine@numerimondes.com"}},"headers":[],"relativePath":"feluqa.rs/get-started/frontend/system-panel.md","filePath":"feluqa.rs/get-started/frontend/system-panel.md"}'),r={name:"feluqa.rs/get-started/frontend/system-panel.md"};function o(i,e,d,l,c,u){return s(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="system-panel-feluqa-core" tabindex="-1">System Panel (Feluqa Core) <a class="header-anchor" href="#system-panel-feluqa-core" aria-label="Permalink to &quot;System Panel (Feluqa Core)&quot;">​</a></h1><p>The System Control Panel is part of the Feluqa Platform. It administers one Platform instance at <code>/system</code>, separately from business application panels.</p><h2 id="sections" tabindex="-1">Sections <a class="header-anchor" href="#sections" aria-label="Permalink to &quot;Sections&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Section</th><th>Purpose</th><th>Minimum privilege</th></tr></thead><tbody><tr><td><strong>Setup</strong></td><td>First-run bootstrap of the <code>platform-owner</code> for this Platform instance</td><td>One-time token</td></tr><tr><td><strong>Users</strong></td><td>Accounts, origin (internal/external), privilege level, sessions</td><td><code>super-admin</code></td></tr><tr><td><strong>Roles and permissions</strong></td><td>Browse the generated permission table, build roles, assign them</td><td><code>super-admin</code> or delegated permission</td></tr><tr><td><strong>Modules</strong></td><td>Install, activate, deactivate, upgrade, uninstall by domain</td><td><code>sysadmin</code></td></tr><tr><td><strong>Features</strong></td><td>Toggle features per license or tenant</td><td><code>sysadmin</code></td></tr><tr><td><strong>Tenants</strong></td><td>Lifecycle: create, suspend, archive, restore</td><td><code>super-admin</code></td></tr><tr><td><strong>Configuration</strong></td><td>Typed settings generated from <code>#[config]</code></td><td><code>sysadmin</code></td></tr><tr><td><strong>Licensing</strong></td><td>License status and domain activation</td><td><code>platform-owner</code></td></tr><tr><td><strong>Audit</strong></td><td>Every allow/deny, privilege change and install action</td><td>Audit permission</td></tr><tr><td><strong>Health</strong></td><td>Version, migrations, storage, backups</td><td><code>staff</code></td></tr></tbody></table><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><ul><li>The System panel is the <strong>only</strong> place where permissions are listed from the generated table. Nothing is created by hand or in a seed.</li><li>Its own handlers are gated like any other: privilege level first, then permission.</li><li>It can be disabled on exposed networks (<code>system.bind = &quot;127.0.0.1&quot;</code> or management port).</li><li>Destructive actions (uninstall, purge data, transfer ownership) require re-authentication and show what data will be kept.</li></ul>',6)])])}const g=t(r,[["render",o]]);export{p as __pageData,g as default};
